mapper.select:
SELECT FROM work_order w JOIN item i ON i.item_code = w.item_code
w.status IN #{status}
ORDER BY CASE w.status WHEN 'IN_PROGRESS' THEN 0 WHEN 'RELEASED' THEN 1 WHEN 'HELD' THEN 2 WHEN 'PLANNED' THEN 3 ELSE 4 END, w.completed_at DESC NULLS LAST, w.priority DESC, w.released_at NULLS LAST, w.created_at LIMIT 200
